 "content": "from collections import deque


def transform(grid):
    """Reverse the nesting order of the colored rectangular layers in each object."""
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            colors = {grid[y][x] for y, x in cells}
            boxes = {}
            for color in colors:
                points = [(y, x) for y, x in cells if grid[y][x] == color]
                boxes[color] = (min(y for y, x in points), max(y for y, x in points),
                                min(x for y, x in points), max(x for y, x in points))
            ordered = sorted(colors, key=lambda col: (
                (boxes[col][1] - boxes[col][0] + 1) * (boxes[col][3] - boxes[col][2] + 1),
                -col), reverse=True)
            recolor = {old: new for old, new in zip(ordered, reversed(ordered))}
            for y, x in cells:
                out[y][x] = recolor[grid[y][x]]
    return out
